import re, numpy as np, resvg_py, io
from PIL import Image
from svgelements import Path, Move, Line, CubicBezier, QuadraticBezier, Close, Arc
svg=open('data_lake/downloads/indonesian-marine-corps-flag/Korps Marinir.svg',encoding='utf8').read()
d=re.search(r'<path\s+style="fill:#000000[^"]*"\s+d="([^"]+)"',svg).group(1)
def r(dd):
    s=f'<svg xmlns="http://www.w3.org/2000/svg" width="600" height="600" viewBox="0 0 600 600"><path fill-rule="evenodd" d="{dd}"/></svg>'
    return np.array(Image.open(io.BytesIO(bytes(resvg_py.svg_to_bytes(svg_string=s,width=600)))))[...,3]>128
A=r(d)
P=Path(d)
print('whole d() differ', (A!=r(P.d())).mean())
def absd(segs):
    o=[]
    for g in segs:
        if isinstance(g,Move): o.append(f'M{g.end.x:.4f},{g.end.y:.4f}')
        elif isinstance(g,Close): o.append('Z')
        elif isinstance(g,Line): o.append(f'L{g.end.x:.4f},{g.end.y:.4f}')
        elif isinstance(g,CubicBezier): o.append(f'C{g.control1.x:.4f},{g.control1.y:.4f} {g.control2.x:.4f},{g.control2.y:.4f} {g.end.x:.4f},{g.end.y:.4f}')
        elif isinstance(g,QuadraticBezier): o.append(f'Q{g.control.x:.4f},{g.control.y:.4f} {g.end.x:.4f},{g.end.y:.4f}')
        else: raise ValueError(type(g))
    return ''.join(o)
print('abs whole differ',(A!=r(absd(P.segments()))).mean())
subs=list(P.as_subpaths())
print('abs subs differ',(A!=r(''.join(absd(s.segments()) if hasattr(s,'segments') else absd(list(s)) for s in subs))).mean())
EOF

