import sys
import numpy as np
sys.argv = ['x']
exec(open('files/orion-sternkarte/fit_projection.py', encoding='utf8').read().split("for kind in")[0])
P = [5.5591, 2.715, 506.6733, -0.0045, 191.334, 229.3006]
pts = []
for s in stars:
    if s[4] > 7 or not (3 < s[2] < 8):
        continue
    x, y = proj(P, s[2], s[3], 'equidist')
    if 4 < x < W - 4 and 4 < y < H - 4:
        d = np.hypot(blobs[:, 0] - x, blobs[:, 1] - y)
        j = np.argmin(d)
        if d[j] < 1.5:
            pts.append((s[4], blobs[j, 2], d[j]))
        else:
            pts.append((s[4], 0, d[j]))
pts = np.array(pts)
for lo in np.arange(-1.5, 7, 0.5):
    m = (pts[:, 0] >= lo) & (pts[:, 0] < lo + 0.5)
    if m.any():
        found = pts[m][pts[m][:, 1] > 0]
        print(f'mag {lo:4.1f}: n={m.sum():3d} drawn={len(found):3d} area med={np.median(found[:, 1]) if len(found) else 0:6.1f} r={np.sqrt(np.median(found[:, 1]) / np.pi) if len(found) else 0:5.2f}')

